      "Content-Type": "text/plain;charset=UTF-8",
      "Origin": "https://cinejoy.pk",
      "Referer": "https://cinejoy.pk/"
    },
    body: ciphertextBody
  });
  const respBuf = Buffer.from(await gatewayRes.arrayBuffer());
  console.log("Gateway returned raw buffer len:", respBuf.length);

  // 1. Valid decrypt
  const validJson = resolver.decryptResponse(respBuf, responseKey, keyId, ephemeralPublic);
  console.log("Valid decrypt succeeded. Status:", validJson.status, "data type:", typeof validJson.data);

  // 2. Corrupted key decrypt
  const badKey = Buffer.from(responseKey);
  badKey[0] ^= 0xff;
  try {
    resolver.decryptResponse(respBuf, badKey, keyId, ephemeralPublic);
    console.error("FAIL: Decryption should have failed with bad key!");
  } catch (err) {
    console.log("PASS: Bad key threw authentication failure as expected:", err.message);
